// Bài 7.5 — origin = giao thức + host + cổng (cổng mặc định bị ẩn)
function originOf(url) {
  let u;
  try { u = new URL(url); } catch { return null; }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') return null;
  return u.origin;
}

