solutionCodeJson.code:
// Bài 7.5 — cùng giao thức, cùng host, cùng cổng
function sameOrigin(a, b) {
  const o = (x) => { try { return new URL(x).origin; } catch { return null; } };
  const oa = o(a);
  return oa !== null && oa !== 'null' && oa === o(b);
}

